// ╔══════════════════════════════════════════════════════════╗
// ║           萤火  /  Lumen Phonia                          ║
// ║   乐谱如草叶在暗处生长，萤火环绕，雨落涟漪，光束探入      ║
// ║   画布 1440×1920  ·  p5.js Web Editor 可运行             ║
// ╚══════════════════════════════════════════════════════════╝

// ╔══════════════════════════════════════════════════════════╗
// ║              内嵌类：音高模型  Pitch                      ║
// ╚══════════════════════════════════════════════════════════╝
// step: 0=C, 1=D, …, 6=B  ·  octave: 八度编号  ·  alter: -1=♭, 0=♮, 1=♯
class Pitch {
  constructor(step, octave, alter = 0) {
    this.step   = step;
    this.octave = octave;
    this.alter  = alter;
  }

  // 计算音符在五线谱上的位置：0 = 底线, 4 = 顶线
  // 高音谱号：底线 = E4,  低音谱号：底线 = G2
  staffPosition(clef) {
    if (clef === 'treble') {
      return (this.step - 2) * 0.5 + (this.octave - 4) * 3.5;
    } else {
      return (this.step - 4) * 0.5 + (this.octave - 2) * 3.5;
    }
  }
}

// ╔══════════════════════════════════════════════════════════╗
// ║           内嵌类：频谱分析  AudioAnalyzer                  ║
// ╚══════════════════════════════════════════════════════════╝
class AudioAnalyzer {
  constructor(fft, sampleRate = 44100) {
    this.fft = fft;
    this.sampleRate = sampleRate;
    this.threshold = 110;    // 最小振幅阈值（0-255）
    this.maxPeaks  = 8;      // 每帧最多提取的峰值数量（增大以覆盖更多频段）
    this.minMidi   = 28;     // E2
    this.maxMidi   = 96;     // C7
  }

  // 半音音阶 → 自然音阶（step + alter）映射表
  static CHROMATIC_MAP = [
    { step: 0, alter: 0 },   // 0  = C
    { step: 0, alter: 1 },   // 1  = C#
    { step: 1, alter: 0 },   // 2  = D
    { step: 1, alter: 1 },   // 3  = D#
    { step: 2, alter: 0 },   // 4  = E
    { step: 3, alter: 0 },   // 5  = F
    { step: 3, alter: 1 },   // 6  = F#
    { step: 4, alter: 0 },   // 7  = G
    { step: 4, alter: 1 },   // 8  = G#
    { step: 5, alter: 0 },   // 9  = A
    { step: 5, alter: 1 },   // 10 = A#
    { step: 6, alter: 0 },   // 11 = B
  ];

  // 分析一帧音频，返回 { treble: NoteInfo[], bass: NoteInfo[] }
  // 确保高音谱表和低音谱表各至少生成一个音符
  analyze() {
    const spectrum = this.fft.analyze();
    const peaks = this._findPeaks(spectrum);

    const MAX_PER_CLEF = 1;
    const treble = [], bass = [];
    const middleC = 60;

    // 第一轮：从全局峰值中分配，分别取各谱表最强的
    for (const peak of peaks) {
      const midi = 69 + 12 * Math.log2(Math.max(peak.freq, 20) / 440);
      if (midi < this.minMidi || midi > this.maxMidi) continue;
      const midiRounded = Math.round(midi);

      if (midiRounded >= middleC && treble.length < MAX_PER_CLEF) {
        treble.push(this._buildNote(peak, midiRounded, 'treble'));
      } else if (midiRounded < middleC && bass.length < MAX_PER_CLEF) {
        bass.push(this._buildNote(peak, midiRounded, 'bass'));
      }
      if (treble.length >= MAX_PER_CLEF && bass.length >= MAX_PER_CLEF) break;
    }

    // 第二轮：若某谱表仍为空，在其专属频段中强制搜索最强频点
    if (treble.length === 0) {
      const p = this._findBestInMIDIRange(spectrum, middleC, this.maxMidi);
      if (p) treble.push(this._buildNote(p,
        Math.round(69 + 12 * Math.log2(Math.max(p.freq, 20) / 440)), 'treble'));
    }
    if (bass.length === 0) {
      const p = this._findBestInMIDIRange(spectrum, this.minMidi, middleC - 1);
      if (p) bass.push(this._buildNote(p,
        Math.round(69 + 12 * Math.log2(Math.max(p.freq, 20) / 440)), 'bass'));
    }

    return { treble, bass };
  }

  // 将峰值数据构建为 NoteInfo 对象
  _buildNote(peak, midiRounded, clef) {
    const octave  = Math.floor(midiRounded / 12) - 1;
    const mapping = AudioAnalyzer.CHROMATIC_MAP[midiRounded % 12];
    const pitch   = new Pitch(mapping.step, octave, mapping.alter);
    return {
      pitch,
      midi: midiRounded,
      alter: mapping.alter,
      staffPos: pitch.staffPosition(clef),
      amplitude: peak.amp / 255,
      clef,
    };
  }

  // 在指定 MIDI 频段内找到最强峰值（局部极大值，无阈值限制）
  _findBestInMIDIRange(spectrum, midiLow, midiHigh) {
    const freqLow  = 440 * Math.pow(2, (midiLow  - 69) / 12);
    const freqHigh = 440 * Math.pow(2, (midiHigh - 69) / 12);
    const nyquist = this.sampleRate / 2;
    const len = spectrum.length;
    const binLow  = Math.max(1,        Math.floor(freqLow  / nyquist * len));
    const binHigh = Math.min(len - 2,  Math.ceil (freqHigh / nyquist * len));

    // 优先找局部峰值
    let bestAmp = 0, bestBin = -1;
    for (let i = binLow; i <= binHigh; i++) {
      if (spectrum[i] > bestAmp &&
          spectrum[i] > spectrum[i - 1] &&
          spectrum[i] > spectrum[i + 1]) {
        bestAmp = spectrum[i];
        bestBin = i;
      }
    }
    // 若无局部峰值，退而取该频段振幅最高的频点
    if (bestBin < 0) {
      for (let i = binLow; i <= binHigh; i++) {
        if (spectrum[i] > bestAmp) { bestAmp = spectrum[i]; bestBin = i; }
      }
    }
    if (bestBin < 0) return null;
    return { freq: this._binToFreq(bestBin, len), amp: bestAmp };
  }

  // 寻找频谱中的局部峰值
  _findPeaks(spectrum) {
    const peaks = [];
    const len = spectrum.length;
    for (let i = 1; i < len - 1; i++) {
      if (spectrum[i] > this.threshold &&
          spectrum[i] > spectrum[i - 1] &&
          spectrum[i] > spectrum[i + 1]) {
        peaks.push({ freq: this._binToFreq(i, len), amp: spectrum[i] });
      }
    }
    peaks.sort((a, b) => b.amp - a.amp);
    return peaks.slice(0, this.maxPeaks);
  }

  // FFT 频率桶索引 → 频率（Hz）
  _binToFreq(bin, numBins) {
    return (bin / numBins) * (this.sampleRate / 2);
  }
}

